class Solution {
public:
    int waysToDistribute(int n, int k) {
        long long MOD = 1e9 + 7;
        vector<long long> dp(k + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            vector<long long> next_dp(k + 1, 0);
            for (int j = 1; j <= min(i, k); j++) {
                next_dp[j] = (dp[j - 1] + (long long)j * dp[j]) % MOD;
            }
            dp = std::move(next_dp);
        }
        return dp[k];
    }
};

class Solution {
    public int waysToDistribute(int n, int k) {
        long MOD = 1_000_000_007L;
        long[] dp = new long[k + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            long[] next = new long[k + 1];
            for (int j = 1; j <= Math.min(i, k); j++) {
                next[j] = (dp[j - 1] + (long)j * dp[j]) % MOD;
            }
            dp = next;
        }
        return (int)dp[k];
    }
}

var waysToDistribute = function(n, k) {
    const MOD = 1000000007n;
    let dp = new Array(k + 1).fill(0n);
    dp[0] = 1n;
    for (let i = 1; i <= n; i++) {
        const next = new Array(k + 1).fill(0n);
        for (let j = 1; j <= Math.min(i, k); j++) {
            next[j] = (dp[j - 1] + BigInt(j) * dp[j]) % MOD;
        }
        dp = next;
    }
    return Number(dp[k]);
};
